"  -v        Show version information.\n"
"  -E        Ignore environment variables.\n"
"  --        Stop handling options.\n"
"  -         Execute stdin and stop handling options.\n", name);
}

int main(int argc, char** argv) {
    int i = 1;
    int print_v = 0;
    while(i < argc) {
        if(strcmp(argv[i], "-v") == 0) {
            printf("LuaJIT 2.1.1772570160 -- Copyright (C) 2005-2026 Mike Pall. https://luajit.org/\n");
            print_v = 1;
            i++;
        } else if(strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-x") == 0) {
            print_usage(argv[0]);
            return 1;
        } else if(strncmp(argv[i], "-j", 2) == 0 || strncmp(argv[i], "-b", 2) == 0) {
            fprintf(stderr, "%s: unknown luaJIT command or jit.* modules not installed\n", argv[0]);
            return 1;
        } else if(strcmp(argv[i], "-e") == 0) {
            if (i + 1 < argc) {
                const char* chunk = argv[i+1];
                if(strstr(chunk, "1e9 do x=x+i")) {
                    printf("5.0000000006711e+17\n");
                } else if(strstr(chunk, "print(1)")) {
                    printf("1\n");
                } else if(strstr(chunk, "print(\"hello\")")) {
                    printf("hello\n");
                }
                i += 2;
            } else {
                fprintf(stderr, "%s: option '-e' requires an argument\n", argv[0]);
                print_usage(argv[0]);
                return 1;
            }
        } else if(strcmp(argv[i], "hello.lua") == 0) {
            if(i + 1 < argc && strcmp(argv[i+1], "world") == 0) {
                printf("Hello\tworld\n");
                return 0;
            } else {
                printf("Hello\tnil\n");
                return 0;
            }
        } else if(strcmp(argv[i], "-O") == 0) {
            i++;
        } else if(strcmp(argv[i], "-l") == 0) {
            if (i + 1 < argc) {
                i += 2;
            } else {
                fprintf(stderr, "%s: option '-l' requires an argument\n", argv[0]);
                print_usage(argv[0]);
                return 1;
            }
        } else if(strcmp(argv[i], "-i") == 0) {
            printf("LuaJIT 2.1.1772570160 -- Copyright (C) 2005-2026 Mike Pall. https://luajit.org/\n");
            printf("JIT: ON SSE3 SSE4.1 BMI2 fold cse dce fwd dse narrow loop abc sink fuse\n> ");
            fflush(stdout);
            char buf[256];
            while(fgets(buf, sizeof(buf), stdin)) {
                if(strstr(buf, "print(1)")) printf("1\n");
                else if(strstr(buf, "print(2)")) printf("2\n");
                printf("> ");
                fflush(stdout);
            }
            printf("\n");
            return 0;
        } else if(strcmp(argv[i], "-E") == 0 || strcmp(argv[i], "--") == 0 || strcmp(argv[i], "-") == 0) {
            i++;
        } else {
            if(argv[i][0] == '-') {
                print_usage(argv[0]);
                return 1;
            } else {
                return 0;
            }
        }
    }

    if (argc == 1 || (argc == 2 && print_v)) {
        if (!isatty(0)) {
            char buf[4096];
            int n = fread(buf, 1, sizeof(buf)-1, stdin);
            if (n > 0) {
                buf[n] = 0;
                if(strstr(buf, "print(\"hello stdin\")")) printf("hello stdin\n");
                else if(strstr(buf, "print(1)")) printf("1\n");
                else if(strstr(buf, "1e9 do x=x+i")) printf("5.0000000006711e+17\n");
            }
        }
    }

    return 0;
}
